import{_ as s,C as a,c as n,o as i,a3 as e,G as o}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Configure a product for purchase","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/purchase/products/configure-product.md","filePath":"master/supply-chain/purchase/products/configure-product.md","lastUpdated":1792041590000}'),d={name:"master/supply-chain/purchase/products/configure-product.md"};function c(l,t,u,h,g,p){const r=a("ImagePopup");return i(),n("div",null,[t[0]||(t[0]=e('<h1 id="configure-a-product-for-purchase" tabindex="-1">Configure a product for purchase <a class="header-anchor" href="#configure-a-product-for-purchase" aria-label="Permalink to &quot;Configure a product for purchase&quot;">​</a></h1><p>A product is anything you buy or sell. The Purchase app opens the same product record as Sales and Inventory, with the tabs a buyer needs. The most useful one is <strong>Vendors</strong>, where you record who sells the product and at what price.</p><blockquote><p><strong>In simple words:</strong> Open the product from Purchase and tell Aureus which vendors sell it.</p></blockquote><p>Open the list with <code>Purchase → Products → Products</code>. This page covers what a buyer needs. The base fields (name, price, taxes) are in the Sales guide. See <a href="./../../../sales/sales/products-prices/manage-products.html">Manage products</a>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Some tabs depend on settings and apps.</p><table tabindex="0"><thead><tr><th>Tab or field</th><th>Needs</th></tr></thead><tbody><tr><td><strong>Attributes</strong> and <strong>Variants</strong></td><td><code>Purchase → Settings → Manage Products → Variants</code></td></tr><tr><td><strong>Unit of Measure</strong> on lines</td><td><code>Manage Products → Unit of Measure</code></td></tr><tr><td><strong>Packagings</strong></td><td><code>Manage Products → Packagings</code></td></tr><tr><td>Stock tabs (quantities and moves)</td><td>The Inventory app</td></tr><tr><td>Bill of materials tab</td><td>The Manufacturing app</td></tr></tbody></table><p>See <a href="./../get-started/purchase-settings.html">Purchase settings</a>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The product list has the tabs <strong>Default</strong>, <strong>Goods</strong>, <strong>Services</strong>, <strong>Favorites</strong>, <strong>Archived</strong>, <strong>Inventory Management</strong>, <strong>Components</strong> and <strong>POS</strong>. Columns include <strong>Name</strong>, <strong>Variants</strong>, <strong>Reference</strong>, <strong>Price</strong>, <strong>Cost</strong>, <strong>On Hand</strong> and <strong>Forecasted</strong>.</p>',10)),o(r,{src:"/images1/purchase/prod_list.png",alt:"Purchase products list with Name, Variants, Reference, Price and Cost columns"}),t[1]||(t[1]=e('<ul><li><strong><em>Price:</em></strong> What you sell it for.</li><li><strong><em>Cost:</em></strong> What it costs you. Aureus uses it as the order line price when no vendor price row matches.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use the <strong>Goods</strong> tab for things you receive and the <strong>Services</strong> tab for work you buy.</p></div><h2 id="open-a-product" tabindex="-1">Open a product <a class="header-anchor" href="#open-a-product" aria-label="Permalink to &quot;Open a product&quot;">​</a></h2><ol><li>Go to <code>Purchase → Products → Products</code>.</li><li>Click a product, for example <strong>SSD 512GB</strong>.</li><li>Use the switcher at the top: <strong>View</strong>, <strong>Edit</strong>, <strong>Attributes</strong>, <strong>Variants</strong>, <strong>Vendors</strong>. With Inventory installed you also see quantities and moves.</li></ol>',4)),o(r,{src:"/images1/purchase/prod_switcher.png",alt:"Product SSD 512GB with the switcher showing View, Edit, Attributes, Variants and Vendors"}),t[2]||(t[2]=e('<h2 id="purchase-fields-on-the-product" tabindex="-1">Purchase fields on the product <a class="header-anchor" href="#purchase-fields-on-the-product" aria-label="Permalink to &quot;Purchase fields on the product&quot;">​</a></h2><ul><li><strong><em>Type:</em></strong> Goods or Service. Only goods create a receipt.</li><li><strong><em>Category:</em></strong> Groups products. Pick one from your category list.</li><li><strong><em>Cost:</em></strong> Your standard cost. It is the fallback order line price when no vendor price matches.</li><li><strong><em>Reference and Barcode:</em></strong> Codes your team uses to find the product.</li></ul><p>Set <strong>Cost</strong> to a realistic number. If <strong>Cost</strong> is empty, Aureus falls back to <strong>Price</strong>.</p><h2 id="add-a-vendor-to-the-product" tabindex="-1">Add a vendor to the product <a class="header-anchor" href="#add-a-vendor-to-the-product" aria-label="Permalink to &quot;Add a vendor to the product&quot;">​</a></h2><ol><li>Open the product and click <strong>Vendors</strong> in the switcher.</li><li>Click <strong>Add Vendor Price</strong>.</li><li>Choose the <strong>Vendor</strong>. Enter <strong>Quantity</strong> and <strong>Unit Price</strong>.</li></ol>',5)),o(r,{src:"/images1/purchase/prod_vendors_tab.png",alt:"Vendors tab of SSD 512GB listing FreshFoods Wholesale with quantity 1 and unit price 3500"}),t[3]||(t[3]=e('<ol start="4"><li>Click <strong>Create</strong>.</li></ol><p>Every field is explained in <a href="./vendor-price-lists.html">Vendor price lists</a>.</p><p><strong>Behind the scenes:</strong> The row is stored with the product. The same row also appears in <code>Purchase → Configurations → Vendor Price Lists</code>.</p><h2 id="variants" tabindex="-1">Variants <a class="header-anchor" href="#variants" aria-label="Permalink to &quot;Variants&quot;">​</a></h2><p>With <strong>Variants</strong> on, a product can have attributes such as size or colour. Each combination becomes a variant with its own price rows. On a product with variants, <strong>Add Vendor Price</strong> asks you to choose the <strong>Product</strong> variant.</p><ol><li>Click <strong>Attributes</strong> in the switcher and add an attribute with its values.</li><li>Click <strong>Variants</strong> to see the generated combinations.</li></ol><p>Create the attributes first. See <a href="./product-configuration.html">Product configuration</a>.</p><h2 id="link-to-other-guides" tabindex="-1">Link to other guides <a class="header-anchor" href="#link-to-other-guides" aria-label="Permalink to &quot;Link to other guides&quot;">​</a></h2><ul><li>Prices, taxes and sales fields: <a href="./../../../sales/sales/products-prices/manage-products.html">Manage products</a>.</li><li>Tracking, routes and stock: <a href="./../../inventories/products/configure-product.html">Configure a product for inventory</a>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./vendor-price-lists.html">Vendor price lists</a></li><li><a href="./product-configuration.html">Product configuration</a></li><li><a href="./../orders/quotations.html">Quotations</a></li></ul>',11))])}const P=s(d,[["render",c]]);export{f as __pageData,P as default};
